                    halt "Newsletter posting failed after three attempts."
                }

                return "Newsletter posted after editor approval."
            } else {
                halt "Webhook configuration or idempotency behavior was not explicitly confirmed; nothing was posted."
            }
        } else {
            return "Newsletter rejected by the editor; nothing was posted."
        }
    } else {
        halt "Release notes were not explicitly confirmed as public; they were not sent to the external model."
    }
